inline const uint8_t* maskFor(int type, bool small) {
  switch (type) {
    case 1:
      return small ? kPawnMaskSmall : kPawnMask;
    case 2:
      return small ? kKnightMaskSmall : kKnightMask;
    case 3:
      return small ? kBishopMaskSmall : kBishopMask;
    case 4:
      return small ? kRookMaskSmall : kRookMask;
    case 5:
      return small ? kQueenMaskSmall : kQueenMask;
    case 6:
      return small ? kKingMaskSmall : kKingMask;
    default:
      return nullptr;
  }
}
